import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { actor, sessionToken, sameOrigin, HttpError } from '../../../src/auth';
import { people, person } from '../../../src/people';
import { appDb } from '../../../src/db';
import { bankRequest, BankError } from '../../../src/banking/client';
import {
  cancelApproval,
  confirmApproval,
  reconcileInterrupted,
  recentIntents,
} from '../../../src/banking/actions';
import { sendMessage, answerWithEvidence } from '../../../src/agent/run';
import { runTool } from '../../../src/agent/tools';
import { caseDetail } from '../../../src/operator/view';
import { documents, readDocument, ingest } from '../../../src/ingestion/pipeline';
import { searchDocuments } from '../../../src/retrieval/search';
import { MissingOpenAIKeyError } from '../../../src/retrieval/embeddings';
import { config } from '../../../src/config';
import { allChunks } from '../../../src/retrieval/store';
import { assessmentForApproval, listRules } from '../../../src/ulises/service';
import { aiUsage, appealLabel } from '../../../src/guardrails/abuse';
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
const json = (data: unknown, status = 200, headers: Record<string, string> = {}) =>
  Response.json(data, { status, headers: { 'Cache-Control': 'no-store', ...headers } });
type RouteContext = { params: Promise<{ path: string[] }> };
function conversationFor(id: string, userId: string) {
  const result = appDb()
    .prepare('SELECT * FROM conversations WHERE id=? AND user_id=?')
    .get(id, userId);
  if (!result) throw new HttpError(404, 'Conversation not found.');
  return result;
}
async function handler(request: Request, context: RouteContext) {
  try {
    const { path } = await context.params;
    if (request.method === 'POST') sameOrigin(request);
    const route = path.join('/');
    if (route === 'health')
      return json({
        ok: true,
        service: 'banana-app',
        chatModel: config.chatModel,
        embeddingModel: config.embeddingModel,
        keyConfigured: !!process.env.OPENAI_API_KEY,
      });
    if (route === 'people') return json(people);
    if (route === 'session' && request.method === 'POST') {
      const { userId } = z.object({ userId: z.string() }).parse(await request.json());
      if (!person(userId)) throw new HttpError(400, 'Unknown person.');
      return json({ person: person(userId) }, 200, {
        'Set-Cookie': `banana_actor=${sessionToken(userId)}; Path=/; HttpOnly; SameSite=Strict`,
      });
    }
    const current = actor(request),
      db = appDb();
    if (route === 'session') return json({ person: current });
    if (route === 'dashboard') {
      if (current.role === 'operator')
        return json({
          incidents: db.prepare('SELECT * FROM incidents ORDER BY created_at DESC').all(),
        });
      await reconcileInterrupted(current.id);
      const [accounts, movements, contacts] = await Promise.all([
        bankRequest(current.id, '/v1/accounts'),
        bankRequest(current.id, '/v1/movements'),
        bankRequest(current.id, '/v1/contacts'),
      ]);
      const approvals = (
        db
          .prepare(
            'SELECT * FROM approvals WHERE user_id=? AND consumed_at IS NULL AND expires_at>?',
          )
          .all(current.id, new Date().toISOString()) as any[]
      ).map((a) => ({ ...a, payload: JSON.parse(a.payload), ulises: assessmentForApproval(a.id) }));
      return json({
        accounts,
        movements,
        contacts,
        approvals,
        transfers: recentIntents(current.id),
        safetyRules: listRules(current.id),
        aiUsage: aiUsage(current.id),
      });
    }
    if (route === 'conversations') {
      if (current.role !== 'customer')
        throw new HttpError(403, 'Select a customer to open a chat.');
      if (request.method === 'POST') {
        const id = randomUUID();
        db.prepare('INSERT INTO conversations VALUES(?,?,?,?)').run(
          id,
          current.id,
          'New conversation',
          new Date().toISOString(),
        );
        return json({ id }, 201);
      }
      return json(
        db
          .prepare('SELECT * FROM conversations WHERE user_id=? ORDER BY created_at DESC')
          .all(current.id),
      );
    }
    if (path[0] === 'conversations' && path[1]) {
      const conversation = conversationFor(path[1], current.id);
      if (path[2] === 'messages' && request.method === 'POST') {
        const { content } = z
          .object({ content: z.string().trim().min(1).max(8000) })
          .parse(await request.json());
        if ((conversation as any).title === 'New conversation')
          db.prepare('UPDATE conversations SET title=? WHERE id=?').run(
            content.slice(0, 50),
            path[1],
          );
        return json(await sendMessage(current.id, path[1], content));
      }
      return json({
        conversation,
        messages: db
          .prepare('SELECT * FROM messages WHERE conversation_id=? ORDER BY created_at,rowid')
          .all(path[1]),
      });
    }
    if (route === 'actions' && request.method === 'POST') {
      const body = z
        .object({
          name: z.enum([
            'transfer_money',
            'request_human',
            'operation_status',
            'list_accounts',
            'search_documents',
            'set_safety_rule',
            'list_safety_rules',
            'remove_safety_rule',
          ]),
          arguments: z.unknown(),
          conversationId: z.string().nullable().optional(),
          intentId: z.string().max(150).optional(),
        })
        .parse(await request.json());
      if (current.role !== 'customer') throw new HttpError(403, 'A customer is required.');
      if (body.conversationId) conversationFor(body.conversationId, current.id);
      const ctx = {
        userId: current.id,
        conversationId: body.conversationId || null,
        runId: randomUUID(),
        intentId: body.intentId || randomUUID(),
      };
      return json(await runTool(body.name, body.arguments, ctx));
    }
    if (path[0] === 'approvals' && path[1] && request.method === 'POST') {
      if (current.role !== 'customer') throw new HttpError(403, 'A customer is required.');
      if (path[2] === 'confirm') {
        const raw = await request.text();
        const { acknowledged } = z
          .object({ acknowledged: z.boolean().optional() })
          .parse(raw ? JSON.parse(raw) : {});
        return json(await confirmApproval(current.id, path[1], { acknowledged }));
      }
      if (path[2] === 'cancel') return json(cancelApproval(current.id, path[1]));
    }
    if (route === 'ai-usage/appeal' && request.method === 'POST') {
      if (current.role !== 'customer') throw new HttpError(403, 'A customer is required.');
      return json(appealLabel(current.id));
    }
    if (path[0] === 'incidents') {
      if (current.role !== 'operator') throw new HttpError(403, 'Operator role required.');
      if (!path[1])
        return json(db.prepare('SELECT * FROM incidents ORDER BY created_at DESC').all());
      return json(await caseDetail(current.id, path[1]));
    }
    if (path[0] === 'documents') {
      const visible = documents().filter(
        (d) => current.role === 'operator' || d.audience === 'public',
      );
      if (path[1]) {
        const doc = visible.find((d) => d.id === path[1]);
        if (!doc) throw new HttpError(404, 'Document not found.');
        if (path[2] === 'chunks')
          return json(
            allChunks()
              .filter((c) => c.documentId === doc.id)
              .map(({ vector, ...c }) => c),
          );
        return json({ ...doc, text: readDocument(doc) });
      }
      return json({
        documents: visible,
        index: db.prepare('SELECT COUNT(*) AS chunks FROM chunks').get(),
      });
    }
    if (route === 'preview-answer' && request.method === 'POST') {
      if (current.role !== 'operator') throw new HttpError(403, 'Operator role required.');
      const body = z
        .object({
          question: z.string().min(1).max(8000),
          sources: z
            .array(
              z.object({
                id: z.string(),
                documentId: z.string(),
                text: z.string().max(12000),
                title: z.string().nullable(),
                version: z.number().nullable(),
                validFrom: z.string().nullable(),
                validTo: z.string().nullable(),
                audience: z.enum(['public', 'internal']),
                score: z.number(),
              }),
            )
            .max(10),
        })
        .parse(await request.json());
      return json(await answerWithEvidence(body.question, body.sources));
    }
    if (route === 'search' && request.method === 'POST') {
      const { query } = z
        .object({ query: z.string().min(1).max(2000) })
        .parse(await request.json());
      return json({ sources: await searchDocuments(query, current.role) });
    }
    if (route === 'ingestion' && request.method === 'POST') {
      if (current.role !== 'operator') throw new HttpError(403, 'Operator role required.');
      return json(await ingest());
    }
    throw new HttpError(404, 'Route not found.');
  } catch (e) {
    if (e instanceof MissingOpenAIKeyError)
      return json({ error: e.message, code: 'missing_openai_api_key' }, 503);
    if (e instanceof HttpError && e.code) return json({ error: e.message, code: e.code }, e.status);
    if (e instanceof HttpError || e instanceof BankError)
      return json({ error: e.message }, e.status);
    if (e instanceof z.ZodError || e instanceof SyntaxError)
      return json({ error: 'Invalid request data.' }, 400);
    console.error('app_request_failed', e instanceof Error ? e.name : 'unknown');
    return json(
      { error: 'The request could not be completed. Check the service and configuration.' },
      500,
    );
  }
}
export const GET = handler;
export const POST = handler;
import Database from 'better-sqlite3';
import fs from 'node:fs';
import path from 'node:path';
import { config } from './config';
let instance: Database.Database | undefined;
export function appDb() {
  if (!instance) {
    fs.mkdirSync(config.dataDir, { recursive: true });
    instance = new Database(path.join(config.dataDir, 'app.sqlite'));
    instance.pragma('journal_mode = WAL');
    instance.pragma('foreign_keys = ON');
    instance.pragma('busy_timeout = 5000');
    instance.exec(`
      CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,title TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),role TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL,run_id TEXT);
      CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,conversation_id TEXT,started_at TEXT NOT NULL,status TEXT NOT NULL,error TEXT);
      CREATE TABLE IF NOT EXISTS intents(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,conversation_id TEXT,run_id TEXT,payload TEXT NOT NULL,status TEXT NOT NULL,bank_reference TEXT,operation_id TEXT,error TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,intent_id TEXT NOT NULL,payload TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT);
      CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,conversation_id TEXT NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,user_id TEXT NOT NULL,conversation_id TEXT,kind TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS chunks(id TEXT PRIMARY KEY,document_id TEXT NOT NULL,text TEXT NOT NULL,title TEXT,version INTEGER,valid_from TEXT,valid_to TEXT,audience TEXT NOT NULL,vector BLOB NOT NULL);
      CREATE TABLE IF NOT EXISTS embedding_cache(key TEXT PRIMARY KEY,vector BLOB NOT NULL);
      CREATE TABLE IF NOT EXISTS ulises_rules(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,label TEXT NOT NULL,when_json TEXT NOT NULL,hold_minutes INTEGER NOT NULL,trusted_contact TEXT,created_at TEXT NOT NULL,removal_requested_at TEXT,removal_effective_at TEXT);
      CREATE TABLE IF NOT EXISTS ulises_assessments(approval_id TEXT PRIMARY KEY,intent_id TEXT NOT NULL,user_id TEXT NOT NULL,conversation_id TEXT,data TEXT NOT NULL,hold_until TEXT,requires_ack INTEGER NOT NULL,acknowledged_at TEXT,incident_id TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS ai_usage(user_id TEXT PRIMARY KEY,data TEXT NOT NULL);
      CREATE INDEX IF NOT EXISTS ulises_rules_user ON ulises_rules(user_id);
      CREATE INDEX IF NOT EXISTS messages_conversation ON messages(conversation_id,created_at);
      CREATE INDEX IF NOT EXISTS incidents_user ON incidents(user_id);
      CREATE INDEX IF NOT EXISTS events_conversation ON events(conversation_id,created_at);
    `);
  }
  return instance;
}
export function closeAppDb() {
  instance?.close();
  instance = undefined;
}
export type Person = {
  id: string;
  name: string;
  role: 'customer' | 'operator';
  initials: string;
  color: string;
};
export type Account = {
  id: string;
  userId: string;
  label: string;
  iban: string;
  balanceCents: number;
};
export type TransferInput = {
  fromAccountId: string;
  toAccountId: string;
  amountCents: number;
  concept: string;
};
export type Operation = TransferInput & {
  id: string;
  userId: string;
  reference: string;
  createdAt: string;
  status: 'completed';
};
export type ToolContext = {
  userId: string;
  conversationId: string | null;
  runId: string;
  intentId: string;
  approvalId?: string;
  // Agent turns reuse an identical open proposal in the same conversation instead of stacking copies.
  dedupeProposals?: boolean;
  // Products the customer holds; document search favours their documentation.
  products?: string[];
};
export type ActionResult = { status: string; [key: string]: unknown };
export type DocumentRecord = {
  id: string;
  title: string;
  file: string;
  version: number;
  validFrom: string;
  validTo: string | null;
  audience: 'public' | 'internal';
  family: string;
};
export type Chunk = {
  id: string;
  documentId: string;
  text: string;
  title: string | null;
  version: number | null;
  validFrom: string | null;
  validTo: string | null;
  audience: string;
  vector?: number[];
};
export type SearchResult = Omit<Chunk, 'vector'> & {
  score: number;
  validity?: 'current' | 'historical' | 'future';
};

