630	  strikes: { at: number; points: number; rule: string }[];
631	  messages: number[];
632	  level: number;
633	  suspendedUntil: number;
634	  lastSuspensionAt: number;
635	  label: Label | null;
636	  history: { at: string; minutes: number; reason: string }[];
637	};
638	export type AiUsageStatus = {
639	  suspended: boolean;
640	  suspendedUntil: string | null;
641	  retryAfterSeconds: number;
642	  level: number;
643	  strikePoints: number;
644	  label: Label | null;
645	  history: State['history'];
646	};
647	
648	const fresh = (): State => ({
649	  strikes: [],
650	  messages: [],
651	  level: 0,
652	  suspendedUntil: 0,
653	  lastSuspensionAt: 0,
654	  label: null,
655	  history: [],
656	});
