658	function load(userId: string, t: number): State {
659	  const row = appDb().prepare('SELECT data FROM ai_usage WHERE user_id=?').get(userId) as
660	    { data: string } | undefined;
661	  const s: State = row ? JSON.parse(row.data) : fresh();
662	  if (s.level > 0 && t - s.lastSuspensionAt > DECAY_MS) {
663	    s.level -= 1;
664	    s.lastSuspensionAt = t;
665	  }
666	  if (s.label && Date.parse(s.label.expires) <= t) s.label = null;
667	  s.strikes = s.strikes.filter((x) => t - x.at <= STRIKE_WINDOW_MS);
668	  s.messages = s.messages.filter((x) => t - x <= 60_000);
669	  return s;
670	}
671	const save = (userId: string, s: State) =>
672	  appDb()
673	    .prepare(
674	      'INSERT INTO ai_usage(user_id,data) VALUES(?,?) ON CONFLICT(user_id) DO UPDATE SET data=excluded.data',
675	    )
676	    .run(userId, JSON.stringify(s));
677	
678	function view(s: State, t: number): AiUsageStatus {
679	  const suspended = s.suspendedUntil > t;
680	  return {
681	    suspended,
682	    suspendedUntil: suspended ? new Date(s.suspendedUntil).toISOString() : null,
683	    retryAfterSeconds: suspended ? Math.ceil((s.suspendedUntil - t) / 1000) : 0,
684	    level: s.level,
685	    strikePoints: s.strikes.reduce((a, x) => a + x.points, 0),
686	    label: s.label,
687	    history: s.history,
688	  };
689	}
