691	function strike(s: State, rule: string, points: number, t: number) {
692	  s.strikes.push({ at: t, points, rule });
693	  if (s.strikes.reduce((a, x) => a + x.points, 0) < STRIKE_THRESHOLD) return;
694	  const ms = SUSPENSION_LADDER_MS[Math.min(s.level, SUSPENSION_LADDER_MS.length - 1)];
695	  const counts = new Map<string, number>();
696	  for (const x of s.strikes) counts.set(x.rule, (counts.get(x.rule) ?? 0) + 1);
697	  const reason = [...counts].map(([r, n]) => `${n}× ${RULE_TEXT[r] ?? r}`).join(', ');
698	  s.level = Math.min(s.level + 1, SUSPENSION_LADDER_MS.length);
699	  s.suspendedUntil = t + ms;
700	  s.lastSuspensionAt = t;
701	  s.strikes = [];
702	  s.messages = [];
703	  s.history.push({ at: new Date(t).toISOString(), minutes: ms / 60_000, reason });
704	  if (s.level >= LABEL_FROM_LEVEL)
705	    s.label = {
706	      label: AI_ABUSER_LABEL,
707	      since: s.label?.since ?? new Date(t).toISOString(),
708	      expires: new Date(t + LABEL_TTL_MS).toISOString(),
709	      reason,
710	      appealed: s.label?.appealed ?? false,
711	    };
712	}
713	
714	export function aiUsage(userId: string, now = Date.now()) {
715	  return view(load(userId, now), now);
716	}
717	
718	// Before a message is processed: counts it for flooding and reports an active suspension.
719	export function admitMessage(userId: string, now = Date.now()) {
720	  const s = load(userId, now);
721	  if (s.suspendedUntil <= now) {
722	    s.messages.push(now);
723	    if (s.messages.length > FLOOD_MAX_PER_MINUTE) strike(s, 'flooding', 2, now);
724	    save(userId, s);
725	  }
726	  return view(s, now);
727	}
728	
729	export function recordScreenEvents(userId: string, events: ScreenEvent[], now = Date.now()) {
730	  const s = load(userId, now);
731	  for (const e of events) if (POINTS[e.rule]) strike(s, e.rule, POINTS[e.rule], now);
732	  save(userId, s);
733	  return view(s, now);
734	}
735	
736	export function appealLabel(userId: string, now = Date.now()) {
737	  const s = load(userId, now);
738	  if (s.label) s.label.appealed = true;
739	  save(userId, s);
740	  return view(s, now);
741	}
742	import { z } from 'zod';
743	import { openai } from '../retrieval/embeddings';
744	import { config } from '../config';
