/* Ulises: payment-pressure check on transfer proposals */
.ulises {
  margin: 12px 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid #6ca381;
  border-radius: 10px;
  background: #f6f8ee;
  font-size: 12px;
}
.ulises-attention {
  border-left-color: #d6b23c;
}
.ulises-high {
  border-left-color: #d9782f;
  background: #fbf3e8;
}
.ulises-scam {
  border-left-color: #c23b33;
  background: #fbecea;
}
.ulises-head {
  display: flex;
  gap: 10px;
  align-items: baseline;
}
.ulises-brand {
  font-weight: 700;
}
.ulises-level {
  flex: 1;
}
.ulises-score {
  font-weight: 700;
}
.ulises-meter {
  height: 6px;
  background: #e5e9dc;
  border-radius: 6px;
  overflow: hidden;
  margin: 8px 0;
}
.ulises-meter span {
  display: block;
  height: 100%;
  background: #6ca381;
}
.ulises-attention .ulises-meter span {
  background: #d6b23c;
}
.ulises-high .ulises-meter span {
  background: #d9782f;
}
.ulises-scam .ulises-meter span {
  background: #c23b33;
}
.ulises-alert {
  font-weight: 700;
  color: #8c241e;
}
.ulises-signals,
.ulises-facts {
  margin: 8px 0;
  padding-left: 18px;
}
.ulises-signals small {
  color: var(--muted);
}
