  margin: 8px 0;
  padding: 10px 12px;
  background: #fff;
  border-left: 3px solid var(--forest);
  border-radius: 0 7px 7px 0;
  font-style: italic;
}
.ulises-rule small {
  display: block;
  font-style: normal;
  color: var(--muted);
}
.ulises-hold {
  font-weight: 700;
}
.ulises-ack {
  display: flex;
  gap: 6px;
  align-items: center;
  font-weight: 700;
}
.ulises-rules p {
  margin: 8px 0 4px;
}
.ulises-rule-row {
  border-bottom: 1px solid var(--line);
  padding-bottom: 8px;
}
.ulises-op {
  font-weight: 700;
}
.ulises-op.ulises-scam {
  color: #8c241e;
}

.approvals .ulises-ack {
  display: flex;
  justify-content: flex-start;
  gap: 8px;
  margin-top: 8px;
}
.approvals .ulises-ack input {
  width: auto;
  margin: 0;
}
