:root {
  --u-calm: #3f8a5c;
  --u-attention: #b98a12;
  --u-high: #d0692a;
  --u-scam: #c23b33;
  --u-good: #2f7d4f;
  --u-warning: #a77a00;
  --u-serious: #c25a1c;
  --u-critical: #b3261e;
}
.ulises-avatar {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #eef3e3;
  font-size: 19px;
}
.ulises-avatar.small {
  width: 28px;
  height: 28px;
  font-size: 14px;
}

/* Panel on a transfer proposal */
.ulises {
  --tone: var(--u-calm);
  --tone-soft: #f2f7ec;
  margin: 14px 0;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(180deg, var(--tone-soft), #fff 140px);
  box-shadow: inset 4px 0 0 var(--tone);
  font-size: 13px;
}
.ulises-attention {
  --tone: var(--u-attention);
  --tone-soft: #fbf6e4;
}
.ulises-high {
  --tone: var(--u-high);
  --tone-soft: #fcf0e6;
}
.ulises-scam {
  --tone: var(--u-scam);
  --tone-soft: #fbe9e7;
}
.ulises-head {
  display: flex;
  gap: 14px;
  align-items: center;
}
.ulises-title {
  flex: 1;
  min-width: 0;
}
.ulises-brand {
  font-weight: 700;
  font-size: 15px;
  margin-right: 8px;
}
.ulises-pill {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  background: var(--tone);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.ulises-verdict {
  margin: 4px 0 0;
  color: var(--ink);
}
.ulises-gauge {
  position: relative;
  width: 64px;
  height: 64px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  align-content: center;
}
.ulises-gauge svg {
  position: absolute;
  inset: 0;
  transform: rotate(-90deg);
}
.ulises-gauge .track {
  fill: none;
  stroke: #e7ebe2;
  stroke-width: 3.5;
}
.ulises-gauge .value {
  fill: none;
  stroke: var(--tone);
  stroke-width: 3.5;
  stroke-linecap: round;
}
.ulises-gauge b {
  font-size: 18px;
  line-height: 1;
}
.ulises-gauge small {
  font-size: 9px;
  color: var(--muted);
}
.ulises-alert {
  margin: 14px 0 0;
  padding: 10px 12px;
  border-radius: 10px;
  background: #fff;
  border: 1px solid #efc9c5;
  font-weight: 700;
  color: #8c241e;
}

/* Before / after balance */
.ulises-balance {
  margin: 16px 0 6px;
  padding: 14px;
  border-radius: 12px;
  background: #fff;
  border: 1px solid var(--line);
}
.ulises-balance-labels {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  margin-bottom: 10px;
}
.ulises-balance-labels span {
  display: grid;
}
.ulises-balance-labels small {
  color: var(--muted);
  font-size: 11px;
}
.ulises-balance-labels b {
  font-size: 17px;
}
.ulises-balance-labels b.is-under {
  color: var(--u-serious);
}
.ulises-balance-labels .arrow {
  color: var(--muted);
  font-size: 18px;
  padding-bottom: 1px;
}
.ulises-balance-bar {
  position: relative;
  display: flex;
  height: 12px;
  border-radius: 6px;
  background: #eef1ea;
  margin-bottom: 22px;
}
.ulises-balance-bar .keep {
  background: var(--forest);
  border-radius: 6px 0 0 6px;
}
.ulises-balance-bar .leave {
  margin-left: 2px;
  border-radius: 0 6px 6px 0;
  background: repeating-linear-gradient(
    135deg,
    var(--tone) 0 4px,
    color-mix(in srgb, var(--tone) 55%, #fff) 4px 8px
  );
}
.ulises-balance-bar .cushion {
  position: absolute;
  top: -4px;
  bottom: -4px;
  width: 2px;
  background: var(--ink);
  border-radius: 1px;
}
.ulises-balance-bar .cushion em {
  position: absolute;
  top: 22px;
  left: 0;
  transform: translateX(-50%);
  white-space: nowrap;
  font-style: normal;
  font-size: 11px;
  color: var(--muted);
}
.ulises-perspective {
  display: flex;
