  margin: 12px 0;
}
.ulises-limits {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px;
  margin: 14px 0;
}
.ulises-limits div {
  display: grid;
  padding: 8px 10px;
  border-radius: 10px;
  background: #fff;
  border: 1px solid var(--line);
}
.ulises-limits small {
  color: var(--muted);
  font-size: 11px;
}
.ulises-home-rules {
  margin-top: 14px;
}
.ulises-rule-row p {
  margin: 8px 0 4px;
}
.ulises-rule-row {
  border-bottom: 1px solid var(--line);
  padding-bottom: 8px;
}
.small-print {
  font-size: 12px;
  margin-bottom: 0;
}

/* Chat banner */
.ulises-banner {
  display: flex;
  gap: 12px;
  align-items: center;
  margin: 0 20px;
  padding: 10px 14px;
  border-radius: 12px;
  background: #f7f1d6;
  border: 1px solid #ece0a8;
}
.ulises-banner p {
  flex: 1;
  margin: 0;
  font-size: 13px;
}

/* The Ulises check (modal) */
.ulises-check-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(23, 43, 43, 0.45);
}
.ulises-check {
  display: flex;
  flex-direction: column;
  width: min(560px, 100%);
  max-height: min(760px, calc(100vh - 32px));
  border-radius: 20px;
  background: var(--paper);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.25);
  overflow: hidden;
}
.ulises-check > header {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 16px 20px;
  background: #fff;
  border-bottom: 1px solid var(--line);
}
.ulises-check > header div {
  flex: 1;
  display: grid;
}
.ulises-check > header small {
  color: var(--muted);
}
.ulises-check-close {
  border: 0;
  background: none;
  font-size: 24px;
  line-height: 1;
  color: var(--muted);
}
.ulises-check-progress {
  height: 3px;
  background: var(--line);
}
.ulises-check-progress span {
  display: block;
  height: 100%;
  background: var(--forest);
  transition: width 0.3s;
}
.ulises-thread {
  flex: 1;
  overflow-y: auto;
  padding: 18px 20px;
  display: grid;
  gap: 10px;
  align-content: start;
}
.ulises-say {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  animation: ulises-in 0.25s ease-out;
}
.ulises-say > p,
.ulises-contract {
  margin: 0;
  padding: 10px 14px;
  border-radius: 4px 14px 14px 14px;
  background: #fff;
  border: 1px solid var(--line);
  max-width: 88%;
}
.ulises-me {
  justify-self: end;
  margin: 8px 0 0 auto;
  width: fit-content;
  max-width: 80%;
  padding: 8px 14px;
  border-radius: 14px 4px 14px 14px;
  background: var(--forest);
  color: #fff;
}
.ulises-contract p {
  margin: 0 0 8px;
}
.ulises-contract dl {
  margin: 0 0 10px;
  display: grid;
  gap: 4px;
}
.ulises-contract dl div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 4px 0;
  border-bottom: 1px dashed var(--line);
}
.ulises-contract dt {
  color: var(--muted);
}
.ulises-contract dd {
  margin: 0;
  font-weight: 700;
  text-align: right;
}
.ulises-contract small {
  color: var(--muted);
}
.ulises-check > footer {
  padding: 12px 20px 16px;
  background: #fff;
  border-top: 1px solid var(--line);
}
.ulises-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ulises-chips button {
  padding: 8px 14px;
  border-radius: 999px;
  border: 1.5px solid var(--forest);
  background: #fff;
  color: var(--forest);
  font-weight: 700;
}
.ulises-chips button:hover {
  background: #eef3e3;
}
.ulises-chips .primary-chip {
  background: var(--forest);
  color: #fff;
}
.ulises-chips .primary-chip:hover {
  background: #123c33;
}
.ulises-check-input {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}
.ulises-check-input input {
  flex: 1;
  min-width: 0;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
}
.ulises-check-problem {
  margin: 0 0 8px;
  color: var(--u-critical);
}
.ulises-back {
  margin-top: 10px;
  border: 0;
  background: none;
  color: var(--muted);
  padding: 0;
}
@keyframes ulises-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ulises-say {
    animation: none;
  }
}

/* Projection under an assistant reply */
.projection {
  margin: 14px 0 4px;
  padding: 14px;
  border-radius: 14px;
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink);
}
.projection figcaption {
  display: flex;
