];

// Unfinished answers survive closing the window or reloading the page (this browser only).
type Draft = { v: 2; at: number; values: Values; answers: string[]; asked: string[] };
const draftKey = (userId: string) => `ulises-check:${userId}`;
function loadDraft(userId: string, steps: number): Draft | null {
  try {
    const d = JSON.parse(localStorage.getItem(draftKey(userId)) || 'null') as Draft | null;
    const fresh = d && d.v === 2 && Date.now() - d.at < 7 * 86_400_000;
    return fresh && d.answers.length <= steps && d.asked.length === d.answers.length ? d : null;
  } catch {
    return null;
  }
}
function storeDraft(userId: string, draft: Draft | null) {
  try {
    if (draft) localStorage.setItem(draftKey(userId), JSON.stringify(draft));
    else localStorage.removeItem(draftKey(userId));
  } catch {}
}

export function UlisesCheck({
  userId,
  profile,
  api,
  onClose,
  onSaved,
}: {
  userId: string;
  profile: AnyRecord;
  api: Api;
  onClose: () => void;
  onSaved: (message: string) => void;
}) {
  const all = steps(profile);
  const start: Values = {
    monthlyIncomeCents: profile.monthlyIncomeCents ?? null,
    monthlySpendCents: profile.monthlySpendCents ?? null,
    cushionCents: profile.cushionCents,
    bigPaymentCents: profile.bigPaymentCents,
    newRecipientHoldMinutes: profile.newRecipientHoldMinutes,
    quietHours: profile.quietHours,
    trustedContact: profile.trustedContact,
  };
  const [saved] = useState(() => loadDraft(userId, all.length));
  const [values, setValues] = useState<Values>(saved?.values ?? start);
  const [answers, setAnswers] = useState<string[]>(saved?.answers ?? []);
  // Each question's wording is frozen once answered, so later answers never rewrite earlier ones.
  const [asked, setAsked] = useState<string[]>(saved?.asked ?? []);
  const [draft, setDraft] = useState('');
  const [problem, setProblem] = useState('');
  const [saving, setSaving] = useState(false);
  const [result, setResult] = useState<AnyRecord | null>(null);
  const end = useRef<HTMLDivElement>(null);
  const index = answers.length;
  const step = all[index];
  useEffect(() => {
    end.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }, [index, result]);
  useEffect(() => {
    if (!result)
      storeDraft(userId, answers.length ? { v: 2, at: Date.now(), values, answers, asked } : null);
  }, [userId, values, answers, asked, result]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  function answer(label: string, value: unknown) {
    setProblem('');
    setDraft('');
    if (step.key !== 'intro') setValues((v) => ({ ...v, [step.key]: value }));
    setAsked((a) => [...a, step.ask(values)]);
    setAnswers((a) => [...a, label]);
  }
  function submitDraft() {
    if (!step?.input || !draft.trim()) return;
    if (step.input === 'text') return answer(draft.trim(), draft.trim().slice(0, 80));
    const cents = readAmount(
      draft,
      values.monthlySpendCents ?? profile.effective?.monthlySpendCents,
    );
    if (!cents)
      return setProblem(
        values.monthlySpendCents || profile.effective?.monthlySpendCents
          ? 'I didn’t get that. Try an amount like 800 or 1.5k, or “3 months”.'
          : 'I didn’t get that. Try an amount like 800 or 1.5k.',
      );
    answer(whole(cents), cents);
  }
  async function save() {
    setSaving(true);
    setProblem('');
    try {
      const r = await api('ulises/profile', values);
      storeDraft(userId, null);
      setResult(r);
      onSaved(r.message);
    } catch (e) {
      setProblem((e as Error).message);
    } finally {
      setSaving(false);
    }
  }

  return (
