  db.prepare('UPDATE ulises_profiles SET draft=NULL,draft_updated_at=NULL WHERE user_id=?').run(
    userId,
  );
  db.prepare('DELETE FROM ulises_profiles WHERE user_id=? AND data IS NULL').run(userId);
